package vn.edu.hcmute.example3; import org.springframework.data.domain.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; @Controller @RequestMapping("/users") public class UserController {private final UserRepository users; UserController(UserRepository u){users=u;} @GetMapping String list(@RequestParam(defaultValue="0")int page,Model m){m.addAttribute("result",users.findAll(PageRequest.of(Math.max(0,page),10,Sort.by("id"))));return "users";}}
